-- PostgreSQL DDL for TediVerify; structure only, no data.

CREATE TABLE "complianceFileLinks" (
  "linkId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fileId" bigint NOT NULL,
  "tokenHash" char(64) NOT NULL,
  "expiresAt" timestamp NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("linkId"),
  CONSTRAINT "complianceFileLinks_uq_compliance_file_link_token" UNIQUE ("tokenHash")
);

CREATE TABLE "complianceFiles" (
  "fileId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "recordType" varchar(50) NOT NULL,
  "fieldName" varchar(100) NOT NULL,
  "fileName" varchar(255) NOT NULL,
  "mimeType" varchar(100) NOT NULL,
  "fileSize" bigint NOT NULL,
  "fileData" bytea NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "sha256" char(64) NOT NULL DEFAULT '',
  PRIMARY KEY ("fileId")
);

CREATE TABLE "complianceUsers" (
  "complianceUserId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(255) NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "countryCode" char(2) DEFAULT NULL,
  "firstName" varchar(255) DEFAULT NULL,
  "middleName" varchar(255) DEFAULT NULL,
  "lastName" varchar(255) DEFAULT NULL,
  "phoneNumber" varchar(50) DEFAULT NULL,
  "dateOfBirth" varchar(50) DEFAULT NULL,
  "gender" varchar(50) DEFAULT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("complianceUserId"),
  CONSTRAINT "complianceUsers_uq_compliance_kyc_identifier" UNIQUE ("kycIdentifier")
);

CREATE TABLE "kycAddress" (
  "kycAddressId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "line1" varchar(255) DEFAULT NULL,
  "lga" varchar(255) DEFAULT NULL,
  "state" varchar(255) DEFAULT NULL,
  "postalCode" varchar(50) DEFAULT NULL,
  "country" varchar(100) DEFAULT NULL,
  "status" varchar(50) NOT NULL,
  "verificationDocumentType" varchar(100) DEFAULT NULL,
  "verifiedAt" timestamp NULL DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "verificationDocumentFileId" bigint DEFAULT NULL,
  PRIMARY KEY ("kycAddressId")
);

CREATE TABLE "kycBusiness" (
  "kycBusinessId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "companyName" varchar(255) DEFAULT NULL,
  "companyNumber" varchar(255) DEFAULT NULL,
  "status" varchar(50) NOT NULL,
  "verifiedAt" timestamp NULL DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "entityType" varchar(80) DEFAULT NULL,
  "taxProfile" varchar(80) DEFAULT NULL,
  "taxId" varchar(100) DEFAULT NULL,
  "companyRegistrationDate" varchar(50) DEFAULT NULL,
  "companyId" varchar(100) DEFAULT NULL,
  "classificationName" varchar(255) DEFAULT NULL,
  "classificationId" varchar(100) DEFAULT NULL,
  "natureOfBusiness" text,
  "providerReference" text,
  PRIMARY KEY ("kycBusinessId")
);

CREATE TABLE "kycBusinessDocuments" (
  "businessDocumentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "kycBusinessId" bigint NOT NULL,
  "documentType" varchar(80) NOT NULL,
  "fileId" bigint NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("businessDocumentId"),
  CONSTRAINT "kycBusinessDocuments_uq_kyc_business_document" UNIQUE ("kycBusinessId","documentType")
);

CREATE TABLE "kycBusinessKeyPersons" (
  "keyPersonId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "kycBusinessId" bigint NOT NULL,
  "role" varchar(80) NOT NULL,
  "fullName" varchar(255) NOT NULL,
  "dateOfBirth" date NOT NULL,
  "phoneNumber" varchar(50) NOT NULL,
  "email" varchar(255) NOT NULL,
  "identificationType" varchar(80) NOT NULL,
  "identificationFileId" bigint NOT NULL,
  "personData" jsonb NOT NULL,
  "migrationKey" varchar(100) DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("keyPersonId"),
  CONSTRAINT "kycBusinessKeyPersons_uq_kyc_business_key_person_migration" UNIQUE ("kycBusinessId","migrationKey")
);

CREATE TABLE "kycBvn" (
  "kycBvnId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "bvn" varchar(32) NOT NULL,
  "firstName" varchar(255) DEFAULT NULL,
  "middleName" varchar(255) DEFAULT NULL,
  "lastName" varchar(255) DEFAULT NULL,
  "provider" varchar(50) DEFAULT NULL,
  "status" varchar(50) NOT NULL,
  "verifiedAt" timestamp NULL DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("kycBvnId")
);

CREATE TABLE "kycIncome" (
  "kycIncomeId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "occupation" varchar(100) DEFAULT NULL,
  "sourceOfFunds" varchar(100) DEFAULT NULL,
  "incomeCurrency" char(3) DEFAULT NULL,
  "incomeRange" varchar(50) DEFAULT NULL,
  "documents" jsonb DEFAULT NULL,
  "status" varchar(50) NOT NULL DEFAULT 'pending',
  "verifiedAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("kycIncomeId")
);

CREATE TABLE "kycNin" (
  "kycNinId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "kycIdentifier" varchar(50) NOT NULL,
  "nin" varchar(32) NOT NULL,
  "firstName" varchar(255) DEFAULT NULL,
  "middleName" varchar(255) DEFAULT NULL,
  "lastName" varchar(255) DEFAULT NULL,
  "gender" varchar(50) DEFAULT NULL,
  "dateOfBirth" varchar(50) DEFAULT NULL,
  "phoneNumber" varchar(50) DEFAULT NULL,
  "address" text,
  "provider" varchar(50) DEFAULT NULL,
  "status" varchar(50) NOT NULL,
  "verifiedAt" timestamp NULL DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "verificationProvider" varchar(100) DEFAULT NULL,
  "verificationReference" text,
  "faceConfidence" double precision DEFAULT NULL,
  "taxId" varchar(100) DEFAULT NULL,
  "taxResidency" varchar(255) DEFAULT NULL,
  "officialPhotoFileId" bigint DEFAULT NULL,
  "verificationPhotoFileId" bigint DEFAULT NULL,
  "ninCardFileId" bigint DEFAULT NULL,
  PRIMARY KEY ("kycNinId")
);

CREATE INDEX "complianceFileLinks_idx_compliance_file_links_expiry" ON "complianceFileLinks" ("expiresAt");
CREATE INDEX "complianceFileLinks_idx_compliance_file_links_file" ON "complianceFileLinks" ("fileId");
CREATE INDEX "complianceFiles_idx_compliance_files_owner" ON "complianceFiles" ("userId","kycIdentifier","recordType");
