CREATE INDEX "kycAddress_idxStatus" ON "kycAddress" ("status");
CREATE INDEX "kycAddress_idxCreatedAt" ON "kycAddress" ("createdAt");
CREATE INDEX "kycBusiness_idxUserId" ON "kycBusiness" ("userId");
CREATE INDEX "kycBusiness_idxKycIdentifier" ON "kycBusiness" ("kycIdentifier");
CREATE INDEX "kycBusiness_idxStatus" ON "kycBusiness" ("status");
