CREATE INDEX "kycBusinessDocuments_idx_kyc_business_documents_file" ON "kycBusinessDocuments" ("fileId");
CREATE INDEX "kycBusinessKeyPersons_idx_kyc_business_key_people" ON "kycBusinessKeyPersons" ("kycBusinessId","role");
CREATE INDEX "kycBusinessKeyPersons_idx_kyc_business_key_person_file" ON "kycBusinessKeyPersons" ("identificationFileId");
CREATE INDEX "kycBvn_idxUserId" ON "kycBvn" ("userId");
CREATE INDEX "kycBvn_idxKycIdentifier" ON "kycBvn" ("kycIdentifier");
CREATE INDEX "kycBvn_idxStatus" ON "kycBvn" ("status");
CREATE INDEX "kycBvn_idxCreatedAt" ON "kycBvn" ("createdAt");
CREATE INDEX "kycIncome_idxUserId" ON "kycIncome" ("userId");
CREATE INDEX "kycIncome_idxKycIdentifier" ON "kycIncome" ("kycIdentifier");
CREATE INDEX "kycIncome_idxStatus" ON "kycIncome" ("status");
CREATE INDEX "kycIncome_idxCreatedAt" ON "kycIncome" ("createdAt");
CREATE INDEX "kycNin_idxUserId" ON "kycNin" ("userId");
